from PIL import Image
import numpy as np
from collections import deque, Counter
im=Image.open('sheet.png').convert('RGBA');a=np.array(im)
def components(mask):
 h,w=mask.shape; seen=np.zeros_like(mask,dtype=bool);out=[]
 for y,x in zip(*np.where(mask)):
  if seen[y,x]:continue
  q=deque([(int(y),int(x))]);seen[y,x]=1;points=[]
  while q:
   cy,cx=q.popleft();points.append((cy,cx))
   for ny,nx in ((cy-1,cx),(cy+1,cx),(cy,cx-1),(cy,cx+1)):
    if 0<=ny<h and 0<=nx<w and mask[ny,nx] and not seen[ny,nx]:
     seen[ny,nx]=1;q.append((ny,nx))
  if len(points)>100:
   p=np.array(points);ys,xs=p.T;out.append((len(p),(int(xs.min()),int(ys.min()),int(xs.max()+1),int(ys.max()+1)),p))
 return sorted(out,key=lambda c:-c[0])
if __name__=='__main__':
 cs=components(a[:,:,3]>=128)
 print('components>=128 count',len(cs))
 for n,b,p in cs:print(n,b)
 print('alpha extremes',int(a[:,:,3].max()),np.sum(a[:,:,3]==255),'semi',np.sum((a[:,:,3]>0)&(a[:,:,3]<255)))
